#include "stdlib/math/base/special/log1pmxf.h"
#include "stdlib/math/base/special/log1pf.h"
#include "stdlib/math/base/special/lnf.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/constants/float32/eps.h"

/**
* Evaluates \\( \operatorname{log1pmxf}(x) = \lnf(1+x) - x \\) for a single-precision floating point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_log1pmxf( 1.1f );
* // returns ~-0.358f
*/
float stdlib_base_log1pmxf( const float x ) {
	float ax;
	if ( x <= -1.0f ) {
		return 0.0f / 0.0f; // NaN
	}
	ax = stdlib_base_absf( x );

	// Large |x|: safe direct computation
	if ( ax > 0.95f ) {
		return stdlib_base_lnf( 1.0f + x ) - x;
	}

	// Very small x: use first Taylor term
	if ( ax < STDLIB_CONSTANT_FLOAT32_EPS ) {
		return -x * x / 2.0f;
	}
	return stdlib_base_log1pf( x ) - x;
}
